class Billion:
    """A sorted sequence of a billion even numbers (position i holds 2 * i) that supports only len() and nums[i], and counts every look."""
    size = 1_000_000_000

    def __init__(self):
        self.looks = 0

    def __len__(self):
        return self.size

    def __getitem__(self, i):
        if not isinstance(i, int):
            raise TypeError("a sequence of a billion numbers can only be read one position at a time, nums[i] (no slices)")
        self.looks += 1
        if self.looks > 500:
            raise AssertionError("looked at more than 500 elements of a list of a billion numbers: binary search needs about 30")
        if i < 0:
            i += self.size
        if not 0 <= i < self.size:
            raise IndexError("list index out of range")
        return 2 * i
