def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1             # if the target is present, its index is in lo..hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1                  # everything up to mid is too small
        else:
            hi = mid - 1                  # everything from mid on is too big
    return -1
